#!/usr/bin/env bun
/**
 * home-first-viewport r2 evidence capture.
 * Hard gate: scrollY === 0 and no AI Activity / projects in the viewport.
 */
import { mkdir, writeFile } from "node:fs/promises";
import { chromium } from "playwright-core";

const OUT =
  "/Users/dhruv2mars/dev/github/portfolio/gauntlet/pieces/home-first-viewport/r2";
await mkdir(OUT, { recursive: true });

const chromeForTesting =
  `${process.env.HOME}/Library/Caches/ms-playwright/chromium-1234/chrome-mac-arm64/Google Chrome for Testing.app/Contents/MacOS/Google Chrome for Testing`;
const headlessShell =
  `${process.env.HOME}/Library/Caches/ms-playwright/chromium_headless_shell-1234/chrome-headless-shell-mac-arm64/chrome-headless-shell`;

let browser;
try {
  browser = await chromium.launch({
    executablePath: chromeForTesting,
    headless: true,
  });
} catch {
  browser = await chromium.launch({
    executablePath: headlessShell,
    headless: true,
  });
}

type Gate = {
  ok: boolean;
  scrollY: number;
  vh: number;
  h1: string | null;
  h1Size: string | null;
  family: string | null;
  introH: number | null;
  introBottom: number | null;
  aiTop: number | null;
  projTop: number | null;
  atmos: boolean;
  stacked: boolean;
};

async function measureGate(page: import("playwright-core").Page): Promise<Gate> {
  return page.evaluate(() => {
    window.scrollTo(0, 0);
    document.documentElement.scrollTop = 0;
    document.body.scrollTop = 0;
    const intro = document.querySelector(".home-intro");
    const h1 = document.querySelector(".home-intro-title");
    const ai = [...document.querySelectorAll("h2")].find((h) =>
      /AI Activity/i.test(h.textContent || ""),
    );
    const projects = [...document.querySelectorAll("h2")].find((h) =>
      /Selected|Featured/i.test(h.textContent || ""),
    );
    const vh = window.innerHeight;
    const aiTop = ai ? ai.getBoundingClientRect().top : null;
    const projTop = projects ? projects.getBoundingClientRect().top : null;
    const ok =
      window.scrollY === 0 &&
      !!intro &&
      !!h1 &&
      (aiTop === null || aiTop >= vh - 1) &&
      (projTop === null || projTop >= vh - 1);
    return {
      ok,
      scrollY: window.scrollY,
      vh,
      h1: h1?.textContent?.replace(/\s+/g, " ").trim() ?? null,
      h1Size: h1 ? getComputedStyle(h1).fontSize : null,
      family: h1 ? getComputedStyle(h1).fontFamily.split(",")[0]!.trim() : null,
      introH: intro ? Math.round(intro.getBoundingClientRect().height) : null,
      introBottom: intro
        ? Math.round(intro.getBoundingClientRect().bottom)
        : null,
      aiTop: aiTop != null ? Math.round(aiTop) : null,
      projTop: projTop != null ? Math.round(projTop) : null,
      atmos: !!document.querySelector(".home-intro-atmosphere"),
      stacked: !!document.querySelector(".home-intro-given"),
    };
  });
}

async function prep(
  page: import("playwright-core").Page,
  width: number,
  height: number,
) {
  await page.setViewportSize({ width, height });
  await page.goto("http://localhost:3000/", {
    waitUntil: "domcontentloaded",
    timeout: 20_000,
  });
  await page.waitForSelector(".home-intro-title", { state: "visible" });
  await page.evaluate(() => {
    if ("scrollRestoration" in history) history.scrollRestoration = "manual";
    const root = document.documentElement;
    root.classList.add("dark");
    root.classList.remove("light");
    try {
      localStorage.setItem("portfolio-theme", "dark");
    } catch {
      /* ignore */
    }
    window.scrollTo(0, 0);
  });
  // Wait for intro enter motion to settle, then re-assert scroll gate
  await page.waitForTimeout(700);
  await page.evaluate(() => window.scrollTo(0, 0));
}

async function capture(
  name: string,
  width: number,
  height: number,
  opts: { hideNav?: boolean } = {},
) {
  const page = await browser.newPage({ deviceScaleFactor: 2 });
  await prep(page, width, height);

  if (opts.hideNav) {
    await page.evaluate(() => {
      const header = document.querySelector("header");
      if (header instanceof HTMLElement) header.style.visibility = "hidden";
      window.scrollTo(0, 0);
    });
    await page.waitForTimeout(200);
  }

  const gate = await measureGate(page);
  console.log(name, gate);
  if (!gate.ok) {
    throw new Error(`HARD GATE FAILED for ${name}: ${JSON.stringify(gate)}`);
  }

  await page.screenshot({ path: `${OUT}/${name}`, fullPage: false });
  await page.close();
  return gate;
}

const gates: Record<string, Gate> = {};
gates.desktop = await capture("first-viewport-desktop.png", 1440, 900);
gates.brandDesktop = await capture("brand-test-no-nav-desktop.png", 1440, 900, {
  hideNav: true,
});
gates.mobile = await capture("first-viewport-mobile.png", 390, 844);
gates.brandMobile = await capture("brand-test-no-nav-mobile.png", 390, 844, {
  hideNav: true,
});

await writeFile(`${OUT}/gate.json`, JSON.stringify(gates, null, 2) + "\n");
await browser.close();
console.log("ALL DONE — hard gate passed for all captures");
